<script setup lang="ts">
import{onMounted,reactive,ref}from'vue'
import{listarHitosRegularizables,regularizarHito,type HitoRegularizable,type Option}from'../services/territorial'
const rows=ref<HitoRegularizable[]>([]),companies=ref<Option[]>([]),phases=ref<Option[]>([]),total=ref(0),last=ref(1),loading=ref(false),saving=ref(false),selected=ref<HitoRegularizable|null>(null),detail=ref(''),file=ref<File|null>(null),error=ref(''),success=ref('')
const filters=reactive({criterio:'',empresa_id:0,fase_id:0,page:1})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const result=await listarHitosRegularizables(filters);rows.value=result.data;total.value=result.total;last.value=result.last_page;companies.value=result.options.empresas;phases.value=result.options.fases}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',empresa_id:0,fase_id:0,page:1});load()}
function open(item:HitoRegularizable){selected.value=item;detail.value=item.detalle;file.value=null;error.value=''}
function pick(event:Event){const selectedFile=(event.target as HTMLInputElement).files?.[0]||null;if(selectedFile&&selectedFile.size>15*1024*1024){error.value='El documento no debe superar 15 MB.';file.value=null;return}file.value=selectedFile}
async function save(){if(!selected.value||detail.value.trim().length<3||!file.value){error.value='Ingrese un comentario de al menos 3 caracteres y el nuevo documento sustentatorio.';return}saving.value=true;try{await regularizarHito(selected.value,{detalle_hito:detail.value,archivo:file.value});success.value='Hito regularizado correctamente.';selected.value=null;await load(filters.page)}catch(e){error.value=message(e)}finally{saving.value=false}}
function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / ENKI / Integración Territorial / Regularización</nav><header class="hero"><div class="mark">RH</div><div><small>ENKI · CONTROL DE HITOS</small><h1>Regularización de fases cerradas</h1><p>Actualiza el sustento y comentario de hitos históricos.</p></div><strong>{{total}} hitos disponibles</strong></header><div v-if="success" class="flash good">✓ {{success}}</div><div v-if="error" class="flash bad">{{error}}</div><section class="filters"><label>Proceso o centro poblado<input v-model.trim="filters.criterio" placeholder="Código o nombre" @keyup.enter="load()"></label><label>EPS<select v-model.number="filters.empresa_id"><option :value="0">Todas</option><option v-for="item in companies" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Fase<select v-model.number="filters.fase_id"><option :value="0">Todas</option><option v-for="item in phases" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><button @click="load()">Buscar</button><button class="clear" @click="clear">Limpiar</button></section><div v-if="loading" class="empty">Cargando hitos cerrados…</div><div v-else-if="!rows.length" class="empty">No existen hitos disponibles para regularización.</div><section v-else class="table"><header><span>Proceso / centro poblado</span><span>EPS</span><span>Fase cerrada</span><span>Cierre</span><span>Sustento</span><span>Acción</span></header><article v-for="item in rows" :key="item.id"><div><b>#{{item.proceso_id}} · {{item.centro_poblado}}</b><small>{{item.detalle}}</small></div><b>{{item.empresa}}</b><span class="phase">{{item.fase}}</span><div><b>{{item.fecha_cierre}}</b><small>{{item.usuario||'Usuario del sistema'}}</small></div><span :class="item.archivo?'yes':'no'">{{item.archivo?'Registrado':'Sin archivo'}}</span><button @click="open(item)">Regularizar</button></article></section><footer v-if="last>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>Página {{filters.page}} de {{last}}</span><button :disabled="filters.page>=last" @click="load(filters.page+1)">Siguiente</button></footer><div v-if="selected" class="backdrop" @mousedown.self="selected=null"><form class="modal" @submit.prevent="save"><header><div><small>PROCESO #{{selected.proceso_id}}</small><h2>Regularizar {{selected.fase}}</h2><p>{{selected.centro_poblado}} · {{selected.empresa}}</p></div><button type="button" @click="selected=null">×</button></header><label>Comentario del hito *<textarea v-model.trim="detail" rows="5"></textarea></label><label>Nuevo documento sustentatorio *<input type="file" @change="pick"><small>Reemplazará el sustento anterior. Tamaño máximo: 15 MB.</small></label><div v-if="selected.archivo" class="current">Archivo actual: {{selected.archivo}}</div><footer><button type="button" class="clear" @click="selected=null">Cancelar</button><button :disabled="saving">{{saving?'Regularizando…':'Confirmar regularización'}}</button></footer></form></div></div></template>
<style scoped>.page{--a:#148f92;color:#35474d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:13px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.5rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.2rem}.hero p{margin:0;color:#7c898f;font-size:.6rem}.hero strong{margin-left:auto;font-size:.48rem}.flash{padding:10px;font-size:.58rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1.3fr 1fr 1fr auto auto;align-items:end;gap:7px;background:#fff}.filters label,.modal label{font-size:.45rem}input,select,textarea{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;background:#fff;font:inherit;font-size:.49rem}.filters button,.pages button,.table article>button,.modal footer button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.46rem}.clear{color:#68767c!important;background:#edf1f2!important}.table{margin-top:12px;background:#fff}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:1.5fr 1fr .8fr .9fr .65fr .6fr;align-items:center;gap:8px;border-bottom:1px solid #e8eded}.table>header{color:#849096;background:#f4f6f7;font-size:.4rem}.table article{font-size:.44rem}.table b,.table small{display:block}.table small{color:#89949a;font-size:.37rem}.phase,.yes,.no{width:max-content;padding:4px 7px;border-radius:9px}.phase{color:#287275;background:#e3f3f3}.yes{color:#267359;background:#e5f5ed}.no{color:#a13e43;background:#fae7e8}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.57rem}.pages{display:flex;justify-content:center;align-items:center;gap:9px;font-size:.47rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(580px,100%);padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.85rem}.modal header p{margin:0;color:#7c898f;font-size:.47rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-top:12px}.modal label small{display:block;margin-top:4px;color:#89949a}.current{margin-top:10px;padding:8px;color:#6f5a24;background:#fff4d8;font-size:.44rem}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:5px}@media(max-width:800px){.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}}@media(max-width:520px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.filters,.table>article{grid-template-columns:1fr}}</style>
